using UnityEngine;using UnityEngine.AI;
namespace Sanctum.Zombies.AI{public sealed class ZombieBrain:MonoBehaviour{[SerializeField]Transform target;[SerializeField]Animator animator;[SerializeField]float attackRange=1.25f,attackCooldown=.9f;NavMeshAgent agent;float nextPath,nextAttack;void Awake()=>agent=GetComponent<NavMeshAgent>();public void BindTarget(Transform t)=>target=t;void Update(){if(!target||!agent)return;if(Time.time>=nextPath){nextPath=Time.time+.15f;agent.SetDestination(target.position);}float d=Vector3.Distance(transform.position,target.position);if(d<=attackRange){agent.isStopped=true;if(Time.time>=nextAttack){nextAttack=Time.time+attackCooldown;animator?.SetTrigger("Attack");}}else agent.isStopped=false;if(animator)animator.SetFloat("Speed",agent.velocity.magnitude);}}}